namespace GA.Domain.Core.Tests;

using GA.Domain.Core.Primitives.Notes;
using GA.Domain.Core.Primitives.Intervals;
using GA.Domain.Core.Theory.Harmony;
using GA.Domain.Core.Theory.Tonal;

[TestFixture]
public class CoreHardeningRegressionTests
{
    [TestCase("b", -1)]
    [TestCase("bb", -2)]
    [TestCase("bbb", -3)]
    public void FlatAccidental_Parse_PreservesValue(string text, int expected) =>
        Assert.That(FlatAccidental.Parse(text).Value, Is.EqualTo(expected));

    [TestCase("#")]
    [TestCase("x")]
    [TestCase("b\n")]
    public void FlatAccidental_TryParse_InvalidNotation_ReturnsFalse(string text) =>
        Assert.That(FlatAccidental.TryParse(text, null, out _), Is.False);

    [TestCase(-1)]
    [TestCase(0)]
    [TestCase(4)]
    [TestCase(9)]
    public void FlatFactories_PreserveNamedNoteAndOctave(int octave) => Assert.Multiple(() =>
    {
        Assert.That(Pitch.Flat.DFlat(octave), Is.EqualTo(new Pitch.Flat(Note.Flat.DFlat, octave)));
        Assert.That(Pitch.Flat.FFlat(octave), Is.EqualTo(new Pitch.Flat(Note.Flat.FFlat, octave)));
        Assert.That(Pitch.Flat.GFlat(octave), Is.EqualTo(new Pitch.Flat(Note.Flat.GFlat, octave)));
    });

    [TestCase(null)]
    [TestCase("")]
    [TestCase("junkC4tail")]
    [TestCase("C4\n")]
    [TestCase("C10")]
    [TestCase("C11")]
    [TestCase("C-2")]
    [TestCase("C99")]
    public void PitchTryParse_InvalidInput_ReturnsFalse(string? input) => Assert.Multiple(() =>
    {
        Assert.That(Pitch.Sharp.TryParse(input, null, out _), Is.False);
        Assert.That(Pitch.Flat.TryParse(input, null, out _), Is.False);
    });

    [TestCase(-1)]
    [TestCase(0)]
    [TestCase(9)]
    public void PitchTryParse_SupportedOctaves_RoundTrip(int octave) => Assert.Multiple(() =>
    {
        Assert.That(Pitch.Sharp.Parse($"C#{octave}"), Is.EqualTo(Pitch.Sharp.CSharp(octave)));
        Assert.That(Pitch.Flat.Parse($"Db{octave}"), Is.EqualTo(new Pitch.Flat(Note.Flat.DFlat, octave)));
    });

    [Test]
    public void FlatNoteParsing_DistinguishesNaturalBFromBFlat() => Assert.Multiple(() =>
    {
        Assert.That(Note.Flat.Parse("B", null), Is.EqualTo(Note.Flat.B));
        Assert.That(Note.Flat.Parse("Bb", null), Is.EqualTo(Note.Flat.BFlat));
        Assert.That(Note.Flat.Parse("D♭", null), Is.EqualTo(Note.Flat.DFlat));
    });

    [Test]
    public void IntervalSizeTryParse_InvalidInput_ReturnsFalse() => Assert.Multiple(() =>
    {
        Assert.That(SimpleIntervalSize.TryParse("x", null, out _), Is.False);
        Assert.That(CompoundIntervalSize.TryParse("x", null, out _), Is.False);
    });

    [Test]
    public void KeyTryParse_InvalidRoot_ReturnsFalse() => Assert.Multiple(() =>
    {
        Assert.That(Key.Major.TryParse("H", out _), Is.False);
        Assert.That(Key.Minor.TryParse("H", out _), Is.False);
    });

    [Test]
    public void KeyGetInterval_MeasuresFromTonicToNote()
    {
        var interval = Key.Major.C.GetInterval(new Note.Accidented(NaturalNote.E));

        Assert.Multiple(() =>
        {
            Assert.That(interval.Size, Is.EqualTo(SimpleIntervalSize.Third));
            Assert.That(interval.Quality, Is.EqualTo(IntervalQuality.Major));
        });
    }

    [Test]
    public void FormulaEquality_ReorderedIntervals_WorkAsDictionaryKeys()
    {
        var first = ChordFormula.FromSemitones("first", 4, 7, 4);
        var reordered = ChordFormula.FromSemitones("reordered", 7, 4, 4);
        Dictionary<ChordFormula, string> lookup = new() { [first] = "found" };
        Assert.Multiple(() =>
        {
            Assert.That(first.Equals(reordered), Is.True);
            Assert.That(reordered.Equals(first), Is.True);
            Assert.That(reordered.GetHashCode(), Is.EqualTo(first.GetHashCode()));
            Assert.That(lookup.TryGetValue(reordered, out _), Is.True);
        });
    }

    [Test]
    public void FormulaEquality_DifferentMultiplicity_IsSymmetric()
    {
        var repeated = ChordFormula.FromSemitones("repeated", 4, 4);
        var major = ChordFormula.Major;
        Assert.Multiple(() =>
        {
            Assert.That(repeated.Equals(major), Is.False);
            Assert.That(major.Equals(repeated), Is.False);
        });
    }

    [Test]
    public void Inversion_WithSharpRoot_ComparesPitchClasses()
    {
        var chord = new Chord(Note.Sharp.C, ChordFormula.Major);
        var inverted = chord.ToInversion(1);
        Assert.Multiple(() =>
        {
            Assert.That(chord.IsInverted, Is.False);
            Assert.That(inverted.IsInverted, Is.True);
            Assert.That(inverted.GetInversion(), Is.EqualTo(1));
            Assert.That(inverted.ToInversion(1).GetInversion(), Is.EqualTo(1));
            Assert.That(inverted.ToInversion(2).GetInversion(), Is.EqualTo(2));
            Assert.That(inverted.ToInversion(0).IsInverted, Is.False);
        });
    }

    [TestCase("C")]
    [TestCase("Cm")]
    [TestCase("Cmaj7")]
    [TestCase("C9")]
    [TestCase("C13")]
    public void ToInversion_PreservesFormulaAndSymbol(string symbol)
    {
        var chord = Chord.FromSymbol(symbol);
        for (var inversion = 0; inversion < chord.Notes.Count; inversion++)
        {
            var inverted = chord.ToInversion(inversion);
            Assert.Multiple(() =>
            {
                Assert.That(inverted.Formula, Is.EqualTo(chord.Formula));
                Assert.That(inverted.Quality, Is.EqualTo(chord.Quality));
                Assert.That(inverted.Symbol, Is.EqualTo(chord.Symbol));
                Assert.That(inverted.GetInversion(), Is.EqualTo(inversion));
                Assert.That(inverted.ToInversion(0).Bass.PitchClass, Is.EqualTo(chord.Root.PitchClass));
            });
        }
    }

    [Test]
    public void NotesConstructor_InvertedNotes_AnalyzesAllNonRootNotes()
    {
        var chord = new Chord(AccidentedNoteCollection.Parse("E G C"), Note.Accidented.Parse("C", null));
        Assert.That(chord.Quality, Is.EqualTo(ChordQuality.Major));
        Assert.That(chord.Formula, Is.EqualTo(ChordFormula.Major));
    }

    [TestCase("Cmaj7")]
    [TestCase("Cmaj9")]
    [TestCase("Cmaj11")]
    [TestCase("Cmaj13")]
    [TestCase("C7")]
    [TestCase("Cm7")]
    [TestCase("C6/9")]
    public void GeneratedSymbol_PreservesChordMeaning(string symbol)
    {
        var parsed = Chord.FromSymbol(symbol);
        var generated = new Chord(parsed.Root, parsed.Formula);
        Assert.Multiple(() =>
        {
            Assert.That(generated.Symbol, Is.EqualTo(symbol));
            Assert.That(Chord.FromSymbol(generated.Symbol).Formula, Is.EqualTo(parsed.Formula));
            Assert.That(parsed.Formula.GetSymbolSuffix(), Is.EqualTo(symbol[1..]));
        });
    }

    [TestCase(1, HarmonicFunction.LeadingTone)]
    [TestCase(2, HarmonicFunction.Subtonic)]
    [TestCase(3, HarmonicFunction.Unknown)]
    public void SeventhDegree_FunctionDependsOnDistanceBelowTonic(
        int semitonesBelowTonic,
        HarmonicFunction expected) =>
        Assert.That(HarmonicFunctionExtensions.FromDegree(7, semitonesBelowTonic), Is.EqualTo(expected));

}

namespace GA.Domain.Core.Tests;

using NUnit.Framework;
using System.Reflection;

/// <summary>
/// Base class for domain tests with common setup and utilities.
/// </summary>
public abstract class DomainTestBase
{
    [SetUp]
    public virtual void Setup()
    {
        // Common setup for all domain tests
        // Can be overridden in derived classes
    }

    [TearDown]
    public virtual void Teardown()
    {
        // Common cleanup for all domain tests
        // Can be overridden in derived classes
    }

    /// <summary>
    /// Asserts that a record has the expected property values.
    /// </summary>
    protected static void AssertRecordProperties<T>(T record, params (string PropertyName, object ExpectedValue)[] expectations)
    {
        foreach (var (propertyName, expectedValue) in expectations)
        {
            var property = typeof(T).GetProperty(propertyName);
            Assert.That(property, Is.Not.Null, $"Property {propertyName} not found on {typeof(T).Name}");
            
            var actualValue = property?.GetValue(record);
            Assert.That(actualValue, Is.EqualTo(expectedValue), 
                $"Property {propertyName} expected {expectedValue} but was {actualValue}");
        }
    }

    /// <summary>
    /// Asserts that an exception of type T is thrown with the expected message.
    /// </summary>
    protected static void AssertException<T>(TestDelegate code) where T : System.Exception
    {
        var exception = Assert.Throws<T>(code);
        // Can add message validation if needed in specific tests
    }

    /// <summary>
    /// Creates a test instance of T with sample data.
    /// </summary>
    protected static T CreateTestInstance<T>()
        => Activator.CreateInstance<T>();
}

namespace GA.Domain.Core.Tests.Instruments;

using System;
using System.Linq;
using GA.Domain.Core.Instruments.Primitives;
using GA.Domain.Core.Primitives.Notes;
using NUnit.Framework;

/// <summary>
///     Characterization tests for <see cref="Fretboard" /> — geometry, the string/fret -> note mapping
///     (string index 0 = Str 1 = high E in standard tuning), and bounds checking.
/// </summary>
[TestFixture]
public class FretboardTests
{
    [Test]
    public void Default_IsSixStringTwentyFourFretGuitar() => Assert.Multiple(() =>
    {
        Assert.That(Fretboard.Default.StringCount, Is.EqualTo(6));
        Assert.That(Fretboard.Default.FretCount, Is.EqualTo(24));
        Assert.That(Fretboard.Default.StringCount, Is.EqualTo(Fretboard.Default.Tuning.StringCount));
    });

    [Test]
    public void CreateGuitar_HonoursRequestedFretCount() => Assert.That(Fretboard.CreateGuitar(12).FretCount, Is.EqualTo(12));

    // Open-string pitch classes for standard tuning, indexed 0 (high E) .. 5 (low E).
    [TestCase(0, 4)]  // E
    [TestCase(1, 11)] // B
    [TestCase(2, 7)]  // G
    [TestCase(3, 2)]  // D
    [TestCase(4, 9)]  // A
    [TestCase(5, 4)]  // E
    public void GetNote_OpenString_HasExpectedPitchClass(int stringIndex, int expectedPc) => Assert.That(Fretboard.Default.GetNote(stringIndex, 0).PitchClass.Value, Is.EqualTo(expectedPc));

    [Test]
    public void GetNote_TwelfthFret_IsSamePitchClassAsOpen()
    {
        // True under both the correct semantics and the current implementation (12 frets = one octave).
        var open = Fretboard.Default.GetNote(0, 0).PitchClass.Value;
        var octave = Fretboard.Default.GetNote(0, 12).PitchClass.Value;
        Assert.That(octave, Is.EqualTo(open));
    }

    // High E string (index 0), fret -> pitch class: each fret raises the pitch one semitone.
    [TestCase(0, 4)]  // E (open)
    [TestCase(1, 5)]  // F
    [TestCase(2, 6)]  // F#
    [TestCase(3, 7)]  // G
    [TestCase(5, 9)]  // A
    [TestCase(12, 4)] // E (one octave up)
    public void GetNote_AppliesFretAsSemitoneOffset(int fret, int expectedPc) => Assert.That(Fretboard.Default.GetNote(0, fret).PitchClass.Value, Is.EqualTo(expectedPc));

    [Test]
    public void GetPitchClass_AgreesWithGetNote() => Assert.That(Fretboard.Default.GetPitchClass(3, 5), Is.EqualTo(Fretboard.Default.GetNote(3, 5).PitchClass));

    [TestCase(-1, 0)]  // string below range
    [TestCase(6, 0)]   // string == StringCount (out of range)
    [TestCase(0, -1)]  // fret below range
    [TestCase(0, 25)]  // fret above FretCount
    public void GetNote_OutOfRange_Throws(int stringIndex, int fret) => Assert.Throws<ArgumentOutOfRangeException>(() => Fretboard.Default.GetNote(stringIndex, fret));

    [Test]
    public void GetPositionsForNote_ReturnsOnlyValidPositions()
    {
        var fretboard = Fretboard.CreateGuitar(12);
        var positions = fretboard.GetPositionsForNote(fretboard.GetNote(0, 0)).ToList();

        Assert.Multiple(() =>
        {
            Assert.That(positions, Is.Not.Empty);
            Assert.That(positions.All(fretboard.IsValidPosition), Is.True);
        });
    }

    // Notes are records of different types (Chromatic, Sharp, Flat, Accidented): a Sharp C never
    // equals the Chromatic C that GetNote returns, so matching must compare pitch classes.
    [Test]
    public void GetPositionsForNote_MatchesByPitchClass_WhateverTheNoteType()
    {
        var fretboard = Fretboard.CreateGuitar(12);
        string[] Locations(Note note) =>
            [.. fretboard.GetPositionsForNote(note).Select(p => $"{p.Location.Str.Value}:{p.Location.Fret.Value}")];

        var expected = Locations(Note.Chromatic.C);

        Assert.Multiple(() =>
        {
            // C on a 12-fret guitar: strings 1..6 at frets 8, 1, 5, 10, 3, 8
            Assert.That(expected, Is.EquivalentTo(new[] { "1:8", "2:1", "3:5", "4:10", "5:3", "6:8" }));
            Assert.That(Locations(Note.Sharp.C), Is.EqualTo(expected));
            Assert.That(Locations(Note.Flat.C), Is.EqualTo(expected));
            Assert.That(Locations(Note.Accidented.C), Is.EqualTo(expected));
            Assert.That(Locations(new Note.Accidented(NaturalNote.B, Accidental.Sharp)), Is.EqualTo(expected));
            Assert.That(fretboard.GetPositionsForNote(Note.Sharp.C).OfType<Position.Played>()
                .All(p => p.MidiNote.PitchClass.Value == 0), Is.True);
        });
    }
}

namespace GA.Domain.Core.Tests.Instruments;

using System;
using GA.Domain.Core.Instruments;
using GA.Domain.Core.Instruments.Primitives;
using GA.Domain.Core.Primitives.Notes;
using NUnit.Framework;

/// <summary>
///     Characterization tests for <see cref="Tuning" /> — string count, open-string pitches (highest
///     string first), and out-of-range indexing.
/// </summary>
[TestFixture]
public class TuningTests
{
    [TestCase(6)]
    public void Default_IsSixStringGuitar(int expected) =>
        Assert.That(Tuning.Default.StringCount, Is.EqualTo(expected));

    [Test]
    public void WellKnownTunings_HaveExpectedStringCounts() =>
        Assert.Multiple(() =>
        {
            Assert.That(Tuning.Ukulele.StringCount, Is.EqualTo(4));
            Assert.That(Tuning.Bass.StringCount, Is.EqualTo(4));
            Assert.That(Tuning.Guitar7String.StringCount, Is.EqualTo(7));
        });

    [Test]
    public void Indexer_String1IsHighestPitch_String6IsLowest()
    {
        // Str 1 is the highest-pitch string (high E4); Str 6 is the lowest (low E2). Both are pitch class E.
        var high = Tuning.Default[(Str)1];
        var low = Tuning.Default[(Str)6];

        Assert.Multiple(() =>
        {
            Assert.That(high.PitchClass.Value, Is.EqualTo(4));
            Assert.That(low.PitchClass.Value, Is.EqualTo(4));
            Assert.That(high > low, Is.True, "String 1 should sound higher than string 6");
        });
    }

    // A tuning is written from one end of the neck to the other, usually from the bass side. A re-entrant
    // string (the 5-string banjo's short drone, the ukulele's high G) sits at one end but is not the lowest
    // pitch, so the first-vs-last pitch comparison alone can pick the wrong end.
    [TestCase("G4 D3 G3 B3 D4", "D4", "G4")] // 5-string banjo, open G: string 5 is the high drone
    [TestCase("G4 C3 G3 B3 D4", "D4", "G4")] // 5-string banjo, C tuning
    [TestCase("G4 C4 E4 A4", "A4", "G4")] // re-entrant ukulele
    [TestCase("E2 A2 D3 G3 B3 E4", "E4", "E2")] // written from the bass side
    [TestCase("E4 B3 G3 D3 A2 E2", "E4", "E2")] // written from the treble side
    public void Indexer_NumbersStringsFromTheTrebleSide(string written, string string1, string lastString)
    {
        var tuning = new Tuning(PitchCollection.Parse(written));

        Assert.Multiple(() =>
        {
            Assert.That(tuning[(Str)1].ToString(), Is.EqualTo(string1));
            Assert.That(tuning[(Str)tuning.StringCount].ToString(), Is.EqualTo(lastString));
        });
    }

    [Test]
    public void AsSpan_LengthMatchesStringCount() =>
        Assert.That(Tuning.Default.AsSpan().Length, Is.EqualTo(Tuning.Default.StringCount));

    [Test]
    // String 7 is a valid Str value but undefined for a 6-string tuning.
    public void Indexer_StringBeyondTuning_Throws() =>
        Assert.Throws<ArgumentOutOfRangeException>(() => _ = Tuning.Default[(Str)7]);
}

namespace GA.Domain.Core.Tests.Instruments;

using GA.Domain.Core.Instruments.Fretboard.Voicings.Core;
using GA.Domain.Core.Instruments.Positions;
using GA.Domain.Core.Instruments.Primitives;
using GA.Domain.Core.Primitives.Notes;
using NUnit.Framework;

/// <summary>
///     Characterization tests for <see cref="Voicing" /> — the diagram-based identity and the derived
///     fret-span / played-count / barre analysis read off the position list.
/// </summary>
[TestFixture]
public class VoicingTests
{
    private static Position Played(int str, int fret) =>
        new Position.Played(new PositionLocation((Str)str, (Fret)fret), (MidiNote)40);

    private static Position Muted(int str) => new Position.Muted((Str)str);

    private static Voicing Make(params Position[] positions) => new(positions, []);

    [Test]
    public void Diagram_RendersFretsAndMutes()
    {
        var voicing = Make(Played(1, 0), Played(2, 2), Muted(3));
        Assert.That(voicing.Diagram, Is.EqualTo("0-2-x"));
    }

    [Test]
    public void PlayedNoteCount_ExcludesMutedStrings()
    {
        var voicing = Make(Played(1, 0), Played(2, 2), Muted(3));
        Assert.That(voicing.PlayedNoteCount, Is.EqualTo(2));
    }

    [Test]
    public void FretSpan_MeasuresAcrossFrettedNotesOnly()
    {
        // Frets 2 and 5 are fretted (open/0 ignored): span = 5 - 2 = 3.
        var voicing = Make(Played(1, 0), Played(2, 2), Played(3, 5));
        Assert.Multiple(() =>
        {
            Assert.That(voicing.FretSpan, Is.EqualTo(3));
            Assert.That(voicing.MinFret, Is.EqualTo(2));
            Assert.That(voicing.MaxFret, Is.EqualTo(5));
        });
    }

    [Test]
    public void FretSpan_AllOpenOrMuted_IsZero()
    {
        var voicing = Make(Played(1, 0), Muted(2));
        Assert.Multiple(() =>
        {
            Assert.That(voicing.FretSpan, Is.EqualTo(0));
            Assert.That(voicing.MinFret, Is.Null);
            Assert.That(voicing.MaxFret, Is.EqualTo(0));
        });
    }

    [Test]
    public void HasBarre_TrueWhenThreeOrMoreShareAFret()
    {
        var barred = Make(Played(1, 3), Played(2, 3), Played(3, 3));
        var notBarred = Make(Played(1, 3), Played(2, 3), Played(3, 5));

        Assert.Multiple(() =>
        {
            Assert.That(barred.HasBarre(), Is.True);
            Assert.That(notBarred.HasBarre(), Is.False);
        });
    }

    // A barre is one finger across fretted strings: open strings share "fret 0" but are not a barre.
    // Frets listed from string 6 (low E) to string 1 (high E), -1 = muted.
    [TestCase(new[] { 0, 3, 2, 0, 1, 0 }, false)]  // open C with E in the bass
    [TestCase(new[] { 0, 2, 2, 1, 0, 0 }, false)]  // open E
    [TestCase(new[] { 3, 2, 0, 0, 0, 3 }, false)]  // open G
    [TestCase(new[] { -1, 0, 2, 2, 1, 0 }, false)] // open Am
    [TestCase(new[] { 1, 3, 3, 2, 1, 1 }, true)]   // F barre chord
    [TestCase(new[] { 3, 5, 5, 4, 3, 3 }, true)]   // G barre chord on the 3rd fret
    public void HasBarre_IgnoresOpenStrings(int[] fretsLowToHigh, bool expected)
    {
        var positions = fretsLowToHigh
            .Select((fret, i) => fret < 0 ? Muted(6 - i) : Played(6 - i, fret))
            .Reverse()
            .ToArray();

        Assert.That(Make(positions).HasBarre(), Is.EqualTo(expected));
    }

    [Test]
    public void HasBarre_FalseForThreeOpenStrings()
    {
        // Open G chord (3-2-0-0-0-3 from low E): three open strings, no barre.
        var openG = Make(Played(1, 3), Played(2, 0), Played(3, 0), Played(4, 0), Played(5, 2), Played(6, 3));

        Assert.That(openG.HasBarre(), Is.False);
    }

    [Test]
    public void Equality_IsBasedOnDiagram_NotNoteArrays()
    {
        var a = new Voicing([Played(1, 0), Played(2, 2)], [(MidiNote)40, (MidiNote)45]);
        var b = new Voicing([Played(1, 0), Played(2, 2)], [(MidiNote)52, (MidiNote)57]);

        Assert.Multiple(() =>
        {
            Assert.That(a, Is.EqualTo(b));
            Assert.That(a.GetHashCode(), Is.EqualTo(b.GetHashCode()));
        });
    }

    [Test]
    public void Equality_DifferentDiagrams_AreNotEqual()
    {
        var a = Make(Played(1, 0), Played(2, 2));
        var b = Make(Played(1, 0), Played(2, 3));
        Assert.That(a, Is.Not.EqualTo(b));
    }

    [Test]
    public void Diagram_IsCached_AndReturnsTheSameInstance()
    {
        var voicing = Make(Played(1, 0), Played(2, 2), Muted(3));
        var first = voicing.Diagram;
        var second = voicing.Diagram;

        Assert.Multiple(() =>
        {
            Assert.That(second, Is.SameAs(first));
            Assert.That(first, Is.EqualTo("0-2-x"));
        });
    }

    [Test]
    public void Diagram_IsRecomputedAfterWithExpression()
    {
        var voicing = Make(Played(1, 0), Played(2, 2));
        _ = voicing.Diagram; // Populate the cache before copying

        var copy = voicing with { Positions = [Played(1, 5), Played(2, 7)] };

        Assert.Multiple(() =>
        {
            Assert.That(copy.Diagram, Is.EqualTo("5-7"));
            Assert.That(voicing.Diagram, Is.EqualTo("0-2"));
            Assert.That(copy, Is.Not.EqualTo(voicing));
        });
    }
}

