/// <summary>
///     Alias resolution in <see cref="CanonicalChordPatternCatalog" />: some chord names are synonyms
///     for the same interval set. <see cref="CanonicalChordPatternCatalog.TryFindExact" /> returns the
///     primary name (lowest priority) and <see cref="CanonicalChordPatternCatalog.FindAllExact" />
///     returns every name, primary first, so the aliases stay reachable.
/// </summary>
[TestFixture]
public class CanonicalChordPatternCatalogTests
{
    // Primary name first, then its aliases.
    private static readonly string[][] _aliasGroups =
    [
        ["augmented-7", "dominant-7-sharp-5"], // C+7 = C7#5: C E G# Bb
        ["major-6-add-9", "6-9"], // C6/9: C D E G A
        ["minor-6-add-9", "minor-6-9"], // Cm6/9: C D Eb G A
        ["9-sus4", "dominant-11"], // C9sus4 = C11 without its third: C D F G Bb
    ];

    private static string Key(int[] intervals) => string.Join(",", intervals.OrderBy(i => i));

    [Test]
    public void DuplicateIntervalSets_AreExactlyTheKnownAliasGroups()
    {
        var duplicates = CanonicalChordPatternCatalog.All
            .GroupBy(p => Key(p.Intervals))
            .Where(g => g.Count() > 1)
            .Select(g => g.OrderBy(p => p.Priority).Select(p => p.Name).ToArray())
            .ToArray();

        Assert.That(duplicates, Is.EquivalentTo(_aliasGroups),
            "a new duplicate interval set needs a decision: add it to the alias groups or remove it");
    }

    [Test]
    public void TryFindExact_ReturnsThePrimaryName() =>
        Assert.Multiple(() =>
        {
            foreach (var group in _aliasGroups)
            {
                var intervals = CanonicalChordPatternCatalog.All.Single(p => p.Name == group[0]).Intervals;
                Assert.That(CanonicalChordPatternCatalog.TryFindExact(intervals)?.Name, Is.EqualTo(group[0]));
            }
        });

    [Test]
    public void FindAllExact_ReturnsPrimaryThenAliases() =>
        Assert.Multiple(() =>
        {
            foreach (var group in _aliasGroups)
            {
                var intervals = CanonicalChordPatternCatalog.All.Single(p => p.Name == group[1]).Intervals;
                var names = CanonicalChordPatternCatalog.FindAllExact(intervals).Select(p => p.Name);
                Assert.That(names, Is.EqualTo(group));
            }
        });

    [Test]
    public void FindAllExact_UniqueIntervalSet_ReturnsOneName()
    {
        var names = CanonicalChordPatternCatalog.FindAllExact([0, 4, 7, 11]).Select(p => p.Name);
        Assert.That(names, Is.EqualTo(new[] { "major-7" }));
    }
}

namespace GA.Domain.Core.Tests.Theory.Harmony;

using System.Collections.Generic;
using System.Linq;
using GA.Domain.Core.Theory.Harmony;
using NUnit.Framework;

/// <summary>
///     <see cref="ChordIntervalPattern.TryMatch" /> counts missing, extra and shared intervals with
///     12-bit masks. These tests compare it with the set arithmetic it replaced, for every pattern of
///     the catalog and every one of the 4096 interval sets, so the rewrite cannot drift.
/// </summary>
[TestFixture]
public class ChordIntervalPatternMatchTests
{
    // The previous implementation, kept here as the reference
    private static MatchResult? Reference(ChordIntervalPattern pattern, IReadOnlyCollection<int> intervals, int maxMissing, int maxExtra)
    {
        var patternSet = new HashSet<int>(pattern.Intervals);
        var voicingSet = new HashSet<int>(intervals);
        var missing = patternSet.Except(voicingSet).Count();
        var extra = voicingSet.Except(patternSet).Count();
        if (missing > maxMissing || extra > maxExtra) return null;
        return new MatchResult(pattern, patternSet.Intersect(voicingSet).Count(), missing, extra);
    }

    private static int[] Intervals(int mask) => [.. Enumerable.Range(0, 12).Where(i => (mask & (1 << i)) != 0)];

    [Test]
    public void TryMatch_AgreesWithSetArithmetic_ForEveryPatternAndEveryIntervalSet()
    {
        var mismatches = 0;
        foreach (var pattern in CanonicalChordPatternCatalog.All)
        {
            for (var mask = 0; mask < 4096; mask++)
            {
                var array = Intervals(mask);
                IReadOnlyCollection<int>[] shapes = [array, new HashSet<int>(array), array.ToList()];
                for (var maxMissing = 0; maxMissing <= 2; maxMissing++)
                for (var maxExtra = 0; maxExtra <= 2; maxExtra++)
                {
                    var expected = Reference(pattern, array, maxMissing, maxExtra);
                    foreach (var shape in shapes)
                    {
                        if (!Equals(pattern.TryMatch(shape, maxMissing, maxExtra), expected)) mismatches++;
                    }
                }
            }
        }

        Assert.That(mismatches, Is.Zero);
    }

    [Test]
    public void TryMatch_KeepsSetSemantics_ForDuplicatesAndOutOfRangeValues()
    {
        var major = CanonicalChordPatternCatalog.All.First(p => p.Name == "major-triad");
        int[][] inputs = [[0, 4, 7, 7, 0], [0, 4, 7, 12], [-1, 0, 4], [0, 4, 7, 19, 24]];

        Assert.Multiple(() =>
        {
            foreach (var input in inputs)
            {
                Assert.That(major.TryMatch(input, 2, 2), Is.EqualTo(Reference(major, input, 2, 2)), string.Join(",", input));
            }
        });
    }
}

